#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Full

COMPONENT Sound : 2

Transform {
  translation 2 0 -1
  children DEF Z SpatialSound {
    intensity 0.5
    location 1 0 0
    direction 1 0 0
    gain 0.4
    coneOuterGain 0.1
    coneInnerAngle 0.4
    coneOuterAngle 1
    distanceModel "LINEAR"
    maxDistance 6
    children DEF O OscillatorSource {
      frequency 220
      periodicWave PeriodicWave {
        type "SAWTOOTH"
      }
      startTime 946684800.048
    }
  }
}

DEF T TimeSensor {
  cycleInterval 0.5
  loop TRUE
}

DEF S Script {
  inputOnly      SFTime  set_time
  outputOnly     SFTime  start
  initializeOnly SFInt32 n 49

  url "ecmascript:
function set_time (value) { if (++ n === 12) start = value; }
"
}

DEF K Script {
  initializeOnly SFNode  z USE Z
  inputOnly      SFTime  set_time
  initializeOnly SFInt32 n 49

  url "ecmascript:
function set_time (value) { ++ n;
   if (n === 18) { z.location = new SFVec3f (1, 0, 0); z.direction = new SFVec3f (1, 0, 0); z.coneInnerAngle = 0.4; z.coneOuterAngle = 1; z.coneOuterGain = 0.1; }
   if (n === 24) { z.distanceModel = 'LINEAR'; z.maxDistance = 6; }
   if (n === 30) { z.gain = 0.4; z.intensity = 0.5; }
}
"
  directOutput TRUE
}

ROUTE T.time TO S.set_time
ROUTE S.start TO O.set_startTime
ROUTE T.time TO K.set_time
